// base64: 6 MiB of generated bytes encoded as base64 (RFC 4648, standard
// alphabet) and decoded again. Prints the encoded length, the sum of its
// character codes and 1 when the decoded bytes equal the original.

const A: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn main() {
    let n: i64 = 6 * 1024 * 1024;
    let data: Vec<u8> = (0..n).map(|i| ((i * 2654435761 >> 13) & 255) as u8).collect();
    let mut enc = Vec::with_capacity(data.len() / 3 * 4);
    for g in data.chunks_exact(3) {
        let bits = (g[0] as u32) << 16 | (g[1] as u32) << 8 | g[2] as u32;
        enc.extend_from_slice(&[A[(bits >> 18 & 63) as usize], A[(bits >> 12 & 63) as usize], A[(bits >> 6 & 63) as usize], A[(bits & 63) as usize]]);
    }
    let mut value = [0u8; 256];
    for (c, &a) in A.iter().enumerate() {
        value[a as usize] = c as u8;
    }
    let mut dec = Vec::with_capacity(data.len());
    for q in enc.chunks_exact(4) {
        let bits = (value[q[0] as usize] as u32) << 18 | (value[q[1] as usize] as u32) << 12 | (value[q[2] as usize] as u32) << 6 | value[q[3] as usize] as u32;
        dec.extend_from_slice(&[(bits >> 16) as u8, (bits >> 8) as u8, bits as u8]);
    }
    let sum: i64 = enc.iter().map(|&b| b as i64).sum();
    println!("{} {} {}", enc.len(), sum, (dec == data) as i32);
}
